@Test
public void filteredGetParameterMap() {
    when(req.getParameterMap()).thenReturn(UtilMisc.toMap("foo", new String[] { "1" }, "bar", new String[] { "2", "3" }));
    when(req.getPathInfo()).thenReturn("/foo");
    Predicate<String> equalsBar = "bar"::equals;
    assertThat(UtilHttp.getParameterMap(req, equalsBar.negate()), Matchers.<Map<String, Object>>allOf(hasEntry("foo", "1"), not(hasEntry("bar", Arrays.asList("2", "3")))));
    assertThat(UtilHttp.getParameterMap(req, equalsBar), Matchers.<Map<String, Object>>allOf(not(hasEntry("foo", "1")), hasEntry("bar", Arrays.asList("2", "3"))));
}

